// ---- 유틸 ----
function esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");}
function seedOf(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
const BIWEEK = 14*864e5;
function modDate(){ return new Date(Math.floor(Date.now()/BIWEEK)*BIWEEK); }
function pubDate(seedStr){ return new Date(Date.parse("2025-08-04") + (seedOf(seedStr)%140)*864e5); }
function ymd(d){ return d.toISOString().slice(0,10); }
function ymdK(d){ const p=ymd(d).split("-"); return p[0]+"."+p[1]+"."+p[2]; }
function htmlResp(b){ return new Response(b,{headers:{"cache-control":"public, max-age=600","content-type":"text/html; charset=UTF-8"}}); }
/* 지역 페이지는 하루 단위로만 내용이 바뀐다. Workers 가 만든 응답은 Cache-Control
   헤더만으로는 엣지에 저장되지 않으므로 Cache API 를 명시적으로 쓴다.
   /api/track 은 POST 라 여기에 걸리지 않고, HTML 렌더 경로에는 서버측 기록이 없다. */
const HTML_CACHE_SEC = 21600;
/* 캐시 키에 버전을 붙인다. 본문을 고친 뒤 이 값을 올리면 이전 엣지 캐시가
   즉시 무시된다 (캐시 비우기 API 권한이 없어도 배포만으로 무효화된다). */
const HTML_CACHE_VER = "10";
function edgeCache(){ return (typeof caches !== "undefined" && caches.default) ? caches.default : null; }
function htmlCacheKey(request){
  try { const u = new URL(request.url); u.searchParams.set("_cv", HTML_CACHE_VER); return new Request(u.toString(), { method: "GET" }); }
  catch(e){ return request; }
}
async function cachedHtmlHit(request){
  const c = edgeCache();
  if(!c || !request || request.method !== "GET") return null;
  try { return (await c.match(htmlCacheKey(request))) || null; } catch(e){ return null; }
}
function htmlRespCached(request, ctx, b){
  const res = new Response(b,{headers:{"cache-control":"public, max-age="+HTML_CACHE_SEC,"content-type":"text/html; charset=UTF-8"}});
  const c = edgeCache();
  if(c && request && request.method === "GET" && ctx && ctx.waitUntil){
    try { ctx.waitUntil(c.put(htmlCacheKey(request), res.clone())); } catch(e){}
  }
  return res;
}

// ---- 룩업/계층 맵 ----
const bySido = new Map();        // ss -> sido(한글)
const sidoList = [];             // [{ss, sido}]
const gugunOf = new Map();       // ss -> [{gg, gu}]
const dongOf = new Map();        // ss/gg -> [region...]
const byDong = new Map();        // ss/gg/ds -> region
for (const r of REGIONS){
  r.url = r.ss + "/" + r.gg + "/" + r.ds;
  byDong.set(r.url, r);
  if(!bySido.has(r.ss)){ bySido.set(r.ss, r.sido); sidoList.push({ss:r.ss, sido:r.sido}); }
  const gk = r.ss;
  if(!gugunOf.has(gk)) gugunOf.set(gk, []);
  if(!gugunOf.get(gk).some(x=>x.gg===r.gg)) gugunOf.get(gk).push({gg:r.gg, gu:r.gu});
  const dk = r.ss + "/" + r.gg;
  if(!dongOf.has(dk)) dongOf.set(dk, []);
  dongOf.get(dk).push(r);
}
sidoList.sort((a,b)=>a.sido.localeCompare(b.sido,"ko"));
for(const [,arr] of gugunOf) arr.sort((a,b)=>a.gu.localeCompare(b.gu,"ko"));
for(const [,arr] of dongOf) arr.sort((a,b)=>a.dong.localeCompare(b.dong,"ko"));
const SIDO_SHORT={seoul:"서울",busan:"부산",daegu:"대구",incheon:"인천",gwangju:"광주",daejeon:"대전",ulsan:"울산",sejong:"세종",gyeonggi:"경기",gangwon:"강원",chungbuk:"충북",chungnam:"충남",jeonbuk:"전북",jeonnam:"전남",gyeongbuk:"경북",gyeongnam:"경남",jeju:"제주"};
